// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.init(address(0x1), address(0x2), address(0x3));
    }
    function testFuzz_property(address recipient, uint256 amount) public {
        // no vm.assume needed - any address and any amount are admissible
        vm.assume(amount >= 0);
        uint256 beforeCount = c.proposalCount();
        vm.prank(address(this));
        c.newGrantProposal(recipient, amount);
        uint256 afterCount = c.proposalCount();
        assertTrue(afterCount == beforeCount + 1, "proposalCount should increment");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 proposalIdx) public {
        // We need C to be initialized to work with external contracts, but our test only
        // cares about newGrantProposal which doesn't interact with external contracts.
        // However, to be safe, we simply initialize with dummy addresses (no adversarial helper needed here).
        c.init(address(uint160(1)), address(uint160(2)), address(uint160(3)));

        // Ensure we have at least one proposal to observe the difference.
        // We can call newGrantProposal multiple times; the fuzzer supplies a proposalIdx.
        // To ensure the bug manifests, we need at least one call. Since the fuzzer picks proposalIdx,
        // we can call newGrantProposal (proposalIdx+1) times to guarantee at least one.
        // But proposalIdx could be large, so bound it to reasonable range.
        uint256 calls = bound(proposalIdx, 0, 50);
        address recipient = address(0xdead);
        uint256 amount = 100;
        for (uint256 i = 0; i < calls; i++) {
            c.newGrantProposal(recipient, amount);
        }

        // The property: proposalCount must equal the number of non-empty mapPID_type entries.
        // Since we only create GRANT proposals and their type is always "GRANT", we can count
        // how many times mapPID_type is set to a non-empty string.
        // In the correct version, proposalCount == calls.
        // In the buggy version, proposalCount == 2 * calls.
        assertTrue(c.proposalCount() == calls);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint88 amount) public {
        // initialize c with dummy supporting addresses so grantFunds won't cause revert-prone calls
        address vader = address(new Helper());
        address usdv = address(new Helper());
        address vault = address(new Helper());
        c.init(vader, usdv, vault);

        // only amount < 2^88 so no overflow in subsequent arithmetic
        vm.assume(amount > 0);
        vm.assume(recipient != address(0));

        // record current proposalCount
        uint256 preCount = c.proposalCount();
        c.newGrantProposal(recipient, uint256(amount));
        uint256 postCount = c.proposalCount();

        // after one newGrantProposal, count should have incremented by exactly 1
        assertTrue(postCount == preCount + 1);

        // The grant details should be stored under the new proposalCount,
        // and the stored recipient should match the one passed.
        // If the mutant stores at proposalCount+1, the retrieval at postCount will return zero values.
        (address storedRecipient, uint256 storedAmount) = c.mapPID_grant(postCount);
        assertTrue(storedRecipient == recipient && storedAmount == uint256(amount));
    }
}

contract Helper {
    // dummy contract that does not revert on calls, used only as placeholder addresses
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address _vader, address _usdv, address _vault) public returns (bool) {
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(
            (c.VADER() == _vader && c.USDV() == _usdv) ||
            (c.VADER() == _usdv && c.USDV() == _usdv)
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public {
        require(_vader != _usdv);
        c.init(_vader, _usdv, _vault);
        address vad = c.VADER();
        bool ok = iVADER(vad).emitting();
        assert(ok == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        uint balBefore = address(c).balance;
        c.init(_vader, _usdv, _vault);
        uint balAfter = address(c).balance;
        assert(balBefore == balAfter);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(address(c.VADER())).call(abi.encodeWithSignature("emitting()"));
    }
}
